INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('azure-sql', 1, 'database', 'tool', 'Azure SQL', 'Azure上で企業向けのリレーショナルデータを管理する', '{"overview":"AzureのマネージドリレーショナルDBサービス。SQL Server互換のエンジンをクラウドで利用できる。","fit":"Azure環境で企業向けのリレーショナルデータを管理したい場合に向く。","caution":"SQL Server固有の機能を使う場合は、互換性の違いを事前に確認する必要がある。","url":"https://azure.microsoft.com/en-us/products/azure-sql"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 4);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('sql-server', 1, 'database', 'tool', 'SQL Server', 'Microsoft系業務システムや既存社内システムのデータを管理する', '{"overview":"Microsoft製のリレーショナルデータベース。Windows Server環境や.NETとの親和性が高い。","fit":"既存の社内システムやMicrosoft系業務システムのデータ管理に向く。","caution":"ライセンスコストがかかる場合があり、オープンソースDBに比べ導入コストが高くなりやすい。","url":"https://www.microsoft.com/en-us/sql-server"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 5);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('sqlite', 1, 'database', 'tool', 'SQLite', '端末内にデータを保存し、インターネットなしでもアプリを利用する', '{"overview":"サーバー不要でファイル一つとして動作する軽量なリレーショナルデータベース。","fit":"デスクトップアプリなど、端末内で完結するデータ保存に向く。","caution":"同時書き込みや大量データ・高負荷アクセスには不向き。","url":"https://www.sqlite.org/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 6);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('dynamodb', 1, 'database', 'tool', 'DynamoDB', 'AWS上で大量アクセスや柔軟なデータ構造に対応する', '{"overview":"AWSのフルマネージドNoSQLデータベース。キーバリュー・ドキュメント型で、大規模アクセスにも自動でスケールする。","fit":"アクセス量が大きく変動するサービスや、柔軟なデータ構造を扱いたい場合に向く。","caution":"リレーショナルな検索やJOINが不得意なため、データ設計をアクセスパターンに合わせて事前に決める必要がある。","url":"https://aws.amazon.com/dynamodb/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 7);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('aurora-serverless', 1, 'database', 'tool', 'Aurora Serverless', 'AWS上で、利用量に応じて自動拡張するリレーショナルDBを利用する', '{"overview":"AWSのリレーショナルDBサービス（Aurora）のサーバーレス版。利用量に応じて自動でスケールする。","fit":"アクセス量の増減が大きいサービスで、リレーショナルDBの機能を維持したまま運用コストを抑えたい場合に向く。","caution":"最小容量を0にして自動停止を利用する場合は、停止状態からの再開に時間がかかることがある。常時応答が必要なシステムでは、最小容量を確保した構成も検討する。","url":"https://aws.amazon.com/rds/aurora/serverless/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 8);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('pgvector', 1, 'database', 'tool', 'pgvector', 'PostgreSQLに文章や画像のベクトル情報を保存し、意味検索やRAGを実現する', '{"overview":"PostgreSQLの拡張機能。文章や画像をベクトル化して保存し、類似度検索を可能にする。","fit":"既存のPostgreSQLをそのまま使い、RAGや意味検索の機能を追加したい場合に向く。","caution":"大規模なベクトルデータでは、専用のベクトルDBに比べ検索速度で劣る場合がある。","url":"https://github.com/pgvector/pgvector"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 9);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('pinecone', 1, 'database', 'tool', 'Pinecone', '大量の文章データを高速に意味検索する', '{"overview":"ベクトル検索に特化したマネージドサービス。大量の文章・埋め込みデータを高速に検索できる。","fit":"大量の文書データを扱うAI検索基盤で、検索速度とスケーラビリティを重視する場合に向く。","caution":"PostgreSQLとは別にデータベースを一つ増やすことになり、運用対象が増える。","url":"https://www.pinecone.io/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 10);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('weaviate', 1, 'database', 'tool', 'Weaviate', 'ベクトル検索とメタデータ検索を組み合わせたAI検索基盤を構築する', '{"overview":"ベクトル検索とメタデータによるフィルタ検索を組み合わせられる、オープンソースのベクトルデータベース。","fit":"検索条件が複雑な高度なAI検索基盤を構築したい場合に向く。","caution":"自前でホスティングする場合は運用の手間が増え、学習コストもやや高い。","url":"https://weaviate.io/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 11);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('redis', 1, 'database', 'tool', 'Redis', 'キャッシュ、セッション、アクセス制限、ジョブキュー、リアルタイムメッセージを高速に処理する', '{"overview":"主にメモリ上でデータを処理する高速なデータストア。キャッシュ、セッション、Pub/Sub、Streams、ジョブキューなどに利用できる。","fit":"データベースへの負荷軽減、ログインセッション、レート制限、非同期処理、リアルタイム通知に向く。","caution":"永続データの主保存先として使うか、消えても復元できるキャッシュとして使うかを明確にする。メモリ上限、削除ポリシー、永続化、冗長化の設計が必要。","url":"https://redis.io/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 12);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('mongodb', 1, 'database', 'tool', 'MongoDB', '項目構成が変化しやすいデータを、JSONに近い形式で柔軟に保存する', '{"overview":"データをBSONドキュメントとして保存するNoSQLデータベース。レコードごとに異なるフィールドを持たせやすい。","fit":"コンテンツ、ログ、イベント、商品属性など、データ構造が頻繁に変化するサービスに向く。","caution":"顧客、契約、請求など関係性が複雑な業務データでは、PostgreSQLなどのリレーショナルDBの方が扱いやすい場合がある。アクセス方法を先に決めてデータ構造を設計する必要がある。","url":"https://www.mongodb.com/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 13);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('prisma', 1, 'orm', 'tool', 'Prisma', 'TypeScriptから型安全にPostgreSQLなどのDBを操作する', '{"overview":"TypeScript向けのORM。スキーマ定義から型安全なクエリコードを自動生成する。","fit":"TypeScriptプロジェクトでPostgreSQLなどのDB操作を型安全に行いたい場合に向く。","caution":"複雑な集計クエリでは生SQLの方が書きやすい場合もあり、使い分けが必要。","url":"https://www.prisma.io/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 0);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('sqlalchemy', 1, 'orm', 'tool', 'SQLAlchemy', 'PythonからPostgreSQLなどのDBを構造的に操作する', '{"overview":"PythonのORM兼SQLツールキット。柔軟なクエリ構築とマイグレーション管理ができる。","fit":"PythonでDBを構造的に扱う業務システムやデータ処理基盤に向く。","caution":"機能が豊富な分、学習コストがやや高く、シンプルな用途にはオーバースペックになりやすい。","url":"https://www.sqlalchemy.org/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 1);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('drizzle-orm', 1, 'orm', 'tool', 'Drizzle ORM', 'TypeScriptからSQLに近い記述で、型安全にデータベースを操作する', '{"overview":"TypeScript向けの軽量なORM兼クエリビルダー。PostgreSQL、MySQL、SQLiteなどを型安全に操作できる。","fit":"SQLの構造を意識しながら、TypeScriptの型安全性も活かしたいNext.jsやHonoのプロジェクトに向く。","caution":"PrismaよりSQLに近い知識が求められる。利用するデータベースやドライバーによる対応機能の違いも確認する。","url":"https://orm.drizzle.team/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 2);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('ef-core', 1, 'orm', 'tool', 'EF Core', 'C#・.NETからSQL ServerやPostgreSQLをオブジェクトとして操作する', '{"overview":"Microsoftが提供する、オープンソースかつクロスプラットフォームの.NET向けORM。LINQによる検索やマイグレーションに対応する。","fit":"ASP.NET Core、Blazor、SQL Serverなどを使ったMicrosoft系業務システムに向く。","caution":"複雑なクエリでは、生成されるSQLと実行性能を確認する必要がある。マイグレーションを本番環境へ適用する手順も設計する。","url":"https://learn.microsoft.com/en-us/ef/core/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 3);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('supabase-auth', 1, 'auth', 'tool', 'Supabase Auth', 'メール、パスワード、SNSログイン、ユーザー管理を実装する', '{"overview":"Supabaseが提供する認証サービス。メール・パスワード・SNSログインなどをまとめて実装できる。","fit":"Supabaseを使うプロジェクトで、追加費用や別サービスなしに認証機能を実装したい場合に向く。","caution":"高度な組織管理・SSOなど企業向け機能は、ClerkやAuth0に比べ限定的。","url":"https://supabase.com/docs/guides/auth"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 0);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('firebase-auth', 1, 'auth', 'tool', 'Firebase Authentication', 'Google、メール、電話番号などによるログインとユーザー管理を行う', '{"overview":"Firebaseが提供する認証サービス。Google・電話番号など多様なログイン方法に対応する。","fit":"Firebase・Firestoreを使うモバイル・Webアプリの認証に向く。","caution":"Firebase以外のバックエンドと組み合わせる場合は、トークン検証の実装を別途行う必要がある。","url":"https://firebase.google.com/docs/auth"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 1);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('clerk', 1, 'auth', 'tool', 'Clerk', 'SaaS向けのログイン、組織管理、プロフィール管理を短期間で実装する', '{"overview":"SaaS向けに特化した認証・ユーザー管理サービス。組織（チーム）管理やプロフィールUIをすぐ使える形で提供する。","fit":"BtoB SaaSで、招待・権限管理を含むユーザー管理を短期間で実装したい場合に向く。","caution":"利用ユーザー数に応じた従量課金があり、規模拡大時のコスト試算が必要。","url":"https://clerk.com/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 2);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('auth0', 1, 'auth', 'tool', 'Auth0', '複数サービス間の認証や企業向け認証を実装する', '{"overview":"Auth0社が提供する認証プラットフォーム。多様なプロトコル（OAuth、SAML等）や企業向け認証に対応する。","fit":"複数サービス間のシングルサインオンや、企業向けの認証要件がある場合に向く。","caution":"設定項目が多く、要件によっては構築・運用にAuth0の専門知識が必要。","url":"https://auth0.com/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 3);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('entra-id', 1, 'auth', 'tool', 'Microsoft Entra ID', 'Microsoft 365や社内アカウントを使ってログインする', '{"overview":"旧Azure AD。Microsoft 365や社内アカウントを使った認証・アクセス管理を行うサービス。","fit":"社内システムでMicrosoft 365アカウントによるログインを求める場合に向く。","caution":"Microsoftエコシステム外のサービスとの連携には、追加設定が必要になることがある。","url":"https://www.microsoft.com/en-us/security/business/identity-access/microsoft-entra-id"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 4);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('cognito', 1, 'auth', 'tool', 'Amazon Cognito', 'AWS上でユーザー登録、ログイン、アクセス権限を管理する', '{"overview":"AWSが提供するユーザー認証・管理サービス。AWSの他サービスとのアクセス権限管理とも連携する。","fit":"AWS上でシステムを構築し、認証もAWS内で完結させたい場合に向く。","caution":"UIのカスタマイズ性がやや低く、独自デザインの認証画面を作る場合は追加実装が必要。","url":"https://aws.amazon.com/cognito/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 5);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('keycloak', 1, 'auth', 'tool', 'Keycloak', '認証基盤を自社環境に設置し、ユーザーや権限を管理する', '{"overview":"オープンソースの認証基盤。自社サーバーに設置して、ユーザー・権限・SSOを一元管理できる。","fit":"外部SaaSに認証情報を預けたくない、セルフホスト前提のシステムに向く。","caution":"サーバーの構築・運用・アップデートを自社で担う必要があり、運用負荷が高い。","url":"https://www.keycloak.org/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 6);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('jwt-custom', 1, 'auth', 'tool', '独自認証・JWT管理', '独自ルールに基づいてログインやAPIアクセスを管理する', '{"overview":"ユーザー情報やアクセス権限を自社で管理し、ログイン後の情報をJWTなどのトークンとしてクライアントとAPIの間で受け渡す方式。","fit":"既存の社内認証との統合など、一般的な認証サービスでは対応できない独自要件がある場合に向く。","caution":"パスワード保存、メール認証、MFA、トークン失効、アカウントロック、攻撃対策まで自社で実装・保守する必要がある。特別な理由がなければ、実績のある認証サービスを優先する。","url":"https://jwt.io/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 7);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('local-auth', 1, 'auth', 'tool', 'ローカル認証', 'アプリを利用する端末内でログインや利用制限を行う', '{"overview":"サーバーを介さず、アプリを利用する端末内だけでログイン・利用制限を行う方式。","fit":"オフラインで動作するデスクトップツールなど、外部通信を前提としないアプリに向く。","caution":"複数端末間でのアカウント共有や不正コピー対策は別途検討が必要。"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 8);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('oauth', 1, 'auth', 'tool', 'OAuth 2.0・外部サービス認可', 'Gmail、Google Drive、Slackなどへのアクセス権限を、ユーザーの許可を得て取得する', '{"overview":"Gmail・Google Drive・Slackなど外部サービスに対して、ユーザーの許可のもと安全にアクセスするための認可の仕組み。","fit":"外部SaaSのデータやAPIを、ユーザーに代わって操作する自動化・連携機能に向く。","caution":"連携先ごとにスコープ設定やトークンの更新処理を実装する必要がある。ログイン用途で使う場合は、OAuth 2.0を基盤にしたOpenID Connectを併用する。","url":"https://oauth.net/2/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 9);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('supabase-storage', 1, 'storage', 'tool', 'Supabase Storage', '画像、PDF、添付ファイルを保存し、ユーザーごとのアクセスを制御する', '{"overview":"Supabaseが提供するファイルストレージ。バケット単位でRow Level Securityによるアクセス制御ができる。","fit":"Supabaseの認証・DBと連携して、ユーザーごとにアクセス制御されたファイル管理をしたい場合に向く。","caution":"大容量・高頻度なファイル配信では、CDNとの組み合わせなど追加の検討が必要になることがある。","url":"https://supabase.com/docs/guides/storage"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 0);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('firebase-storage', 1, 'storage', 'tool', 'Cloud Storage for Firebase', 'モバイル・Webアプリから写真や動画、ファイルを保存する', '{"overview":"Firebaseが提供するファイルストレージ。モバイル・Web SDKからの直接アップロードに対応する。","fit":"Firebaseを使うモバイル・Webアプリで、写真や動画を扱いたい場合に向く。","caution":"Firebase以外のバックエンドと組み合わせる場合、アクセス制御ルールの設計を別途行う必要がある。","url":"https://firebase.google.com/docs/storage"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 1);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('s3', 1, 'storage', 'tool', 'Amazon S3', '大量の画像、PDF、バックアップデータを安全に保存する', '{"overview":"AWSが提供するオブジェクトストレージ。高い耐久性とスケーラビリティを持ち、業界標準的に使われる。","fit":"大量の画像・PDF・バックアップデータを長期的かつ安全に保存したい場合に向く。","caution":"アクセス権限設定（バケットポリシー）を誤ると情報漏えいにつながるため、設定の確認が重要。","url":"https://aws.amazon.com/s3/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 2);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('azure-blob', 1, 'storage', 'tool', 'Azure Blob Storage', 'Azure上で画像、文書、バックアップを保存する', '{"overview":"Azureが提供するオブジェクトストレージ。Azureの他サービスとの連携がしやすい。","fit":"Azure環境で画像・文書・バックアップを保存したい企業システムに向く。","caution":"AWS S3とはAPI・料金体系が異なるため、他クラウドからの移行時は設計の見直しが必要。","url":"https://azure.microsoft.com/en-us/products/storage/blobs"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 3);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('minio', 1, 'storage', 'tool', 'MinIO', 'S3に近いファイル保存環境を自社サーバーに構築する', '{"overview":"S3互換のAPIを持つオープンソースのオブジェクトストレージ。自社サーバーに構築できる。","fit":"外部クラウドを使わず、S3と同じ操作感でファイル保存基盤を自社運用したい場合に向く。","caution":"サーバーの冗長化やバックアップなど、可用性の担保を自社で設計する必要がある。","url":"https://min.io/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 4);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('nas-local', 1, 'storage', 'tool', 'NAS・ローカルファイル', '社内ネットワークや利用端末内にファイルを保存する', '{"overview":"社内ネットワークのNASや、アプリを利用する端末内にファイルを保存する方式。","fit":"外部にデータを出せない社内環境や、オフライン前提のデスクトップアプリに向く。","caution":"遠隔地からのアクセスや冗長化が難しく、災害時のデータ保全対策が別途必要。"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 5);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('openai-api', 1, 'ai', 'tool', 'OpenAI API', '文章生成、画像・音声の理解、データ抽出、ツール実行、AIエージェントを実装する', '{"overview":"OpenAIが提供するAIモデルと開発API。テキスト生成、画像・音声入力、構造化データ出力、ツール呼び出し、ファイル検索などを利用できる。","fit":"チャット、文章生成、分類、データ抽出、文書検索、外部ツールを操作するAIエージェントを短期間で実装したい場合に向く。","caution":"モデルごとに性能、速度、料金、入力上限が異なる。新規のエージェント実装ではResponses APIまたはAgents SDKを基準にし、モデル名を固定しすぎない設計にする。","url":"https://platform.openai.com/docs"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 0);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('claude-api', 1, 'ai', 'tool', 'Claude API', '長文の読解、要約、文章生成、文書問い合わせを実装する', '{"overview":"Anthropicが提供するAIモデルのAPI。長文の読解や要約、文書に基づく応答に強みを持つ。","fit":"長い社内文書やマニュアルを読み込ませて、要約や問い合わせ対応をさせたい場合に向く。","caution":"OpenAI APIと同様に従量課金であり、扱う文書量に応じたコスト設計が必要。","url":"https://www.anthropic.com/api"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 1);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('langgraph', 1, 'ai', 'tool', 'LangGraph', '複数ステップのAI処理、分岐、再試行、状態管理を行う', '{"overview":"AI処理を「状態を持つグラフ」として組み立てられるフレームワーク。分岐や再試行を含む複数ステップの処理を管理できる。","fit":"単純な一問一答ではなく、複数ステップで判断しながら動くAIエージェントを構築したい場合に向く。","caution":"処理フローが複雑になりやすく、設計・デバッグにAIエージェント特有のノウハウが必要。","url":"https://www.langchain.com/langgraph"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 2);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('langchainjs', 1, 'ai', 'tool', 'LangChain.js', 'TypeScriptでAIモデル、検索、外部ツールを組み合わせる', '{"overview":"TypeScript・JavaScript向けのAI開発フレームワーク。AIモデルと検索・外部ツールの連携を組み立てやすくする。","fit":"フロントからバックエンドまでTypeScriptで統一したAI SaaSを構築したい場合に向く。","caution":"アップデートが頻繁で、バージョン間の破壊的変更に注意が必要。","url":"https://js.langchain.com/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 3);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('n8n', 1, 'ai', 'tool', 'n8n', 'Gmail、スプレッドシート、チャット、外部SaaSをつないで業務を自動化する', '{"overview":"ノーコード・ローコードで業務フローを自動化できるワークフローツール。多数の外部SaaSとの連携ノードを持つ。","fit":"Gmailやスプレッドシート、チャットツールなどをつないだ定型業務の自動化に向く。","caution":"複雑な条件分岐やカスタム処理が多い場合は、コードでの実装の方が保守しやすいことがある。","url":"https://n8n.io/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 4);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('rag', 1, 'ai', 'tool', 'RAG構成', 'PDFや社内資料を検索し、根拠となる文書を使ってAIが回答する', '{"overview":"検索（Retrieval）と生成（Generation）を組み合わせ、社内資料などの根拠文書をもとにAIが回答する構成。特定の製品ではなく設計パターン。","fit":"PDFや社内資料への問い合わせに対し、出典を示しながら正確に回答させたい場合に向く。","caution":"検索精度が回答品質に直結するため、文書の分割方法や埋め込みモデルの選定が重要になる。"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 5);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('gemini-api', 1, 'ai', 'tool', 'Gemini API', '文章、画像、音声、動画を扱うマルチモーダルAI機能を実装する', '{"overview":"Googleが提供する生成AIモデルのAPI。テキスト生成、画像・音声・動画入力、ストリーミング、リアルタイム処理などに対応する。","fit":"Google CloudやFirebaseとの親和性を重視するAIアプリや、画像・動画などを含むマルチモーダル処理に向く。","caution":"モデルごとに性能、料金、提供状態、レート制限が異なる。プレビュー版と安定版を区別し、モデル変更に対応できる構成にする。","url":"https://ai.google.dev/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 6);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('vercel-ai-sdk', 1, 'ai', 'tool', 'AI SDK', 'TypeScriptでAIチャット、ストリーミング、構造化出力、ツール実行を実装する', '{"overview":"複数のAIプロバイダーを共通的なインターフェースで扱うためのTypeScript向けツールキット。React、Next.js、Vue、Svelte、Node.jsなどに対応する。","fit":"Next.jsやReactを使って、AIチャット画面やツール実行型AIを短期間で構築したい場合に向く。","caution":"プロバイダー固有の最新機能が、共通インターフェースへ反映されるまで時間差が生じることがある。特定モデルへの依存部分を分離して設計する。","url":"https://ai-sdk.dev/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 7);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('mcp', 1, 'ai', 'tool', 'Model Context Protocol（MCP）', 'AIアプリから外部ツール、データベース、ファイル、業務サービスへ共通方式で接続する', '{"overview":"AIアプリケーションと外部システムを接続するためのオープンな標準プロトコル。サーバー側から、データ、ツール、プロンプトなどをAIへ提供できる。","fit":"複数のAIクライアントから、社内システム、データベース、外部APIを共通方式で利用したい場合に向く。","caution":"ツールへ与える権限、ユーザー認証、承認操作、入力値検証、監査ログが重要。仕様更新にも追従できるよう、プロトコル部分を分離して実装する。","url":"https://modelcontextprotocol.io/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 8);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('opensearch', 1, 'ai', 'tool', 'OpenSearch', '大量のデータに対して、キーワード検索とベクトル検索を組み合わせる', '{"overview":"全文検索、ログ分析、フィルタ検索、ベクトル検索に対応するオープンソースの検索基盤。","fit":"商品検索、社内文書検索、ログ分析など、キーワード一致と意味検索の両方が必要なシステムに向く。","caution":"インデックス、シャード、メモリ、検索クエリなどの設計が必要。小規模な検索ではPostgreSQLやpgvectorの方が運用しやすい場合がある。","url":"https://opensearch.org/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 9);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('vercel', 1, 'hosting', 'tool', 'Vercel', 'React、Next.js、VueなどのWebアプリを簡単に公開し、プレビュー環境を作る', '{"overview":"Next.jsの開発元が提供するホスティングサービス。Gitと連携したプレビュー環境の自動生成に強みを持つ。","fit":"React・Next.js・Vueなどのフロントエンドを素早く公開し、レビュー用のプレビューURLを共有したい場合に向く。","caution":"サーバー処理を多く含む構成では、実行時間や料金プランの制限を事前に確認する必要がある。","url":"https://vercel.com/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 0);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('railway', 1, 'hosting', 'tool', 'Railway', 'NestJSなどのAPIやPostgreSQLを比較的簡単に公開する', '{"overview":"NestJSなどのAPIサーバーやPostgreSQLを、比較的簡単な設定でデプロイできるホスティングサービス。","fit":"Vercelだけでは完結しないAPI・DB込みの構成を、シンプルな手順で公開したい場合に向く。","caution":"大規模トラフィックへの対応やインフラの細かい制御は、AWS等の主要クラウドに比べ制限がある。","url":"https://railway.app/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 1);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('firebase-hosting', 1, 'hosting', 'tool', 'Firebase Hosting', '静的なWebサイト、SPA、Flutter WebをFirebase上で公開する', '{"overview":"Firebaseが提供する静的サイト・SPA向けのホスティングサービス。CDN配信とSSLが標準で付く。","fit":"Flutter WebやSPAなど、静的ビルド成果物を配信したい場合に向く。","caution":"サーバーサイドの動的処理が必要な場合はFirebase App HostingやCloud Functionsとの併用が必要。","url":"https://firebase.google.com/docs/hosting"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 2);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('firebase-app-hosting', 1, 'hosting', 'tool', 'Firebase App Hosting', 'Next.jsなどの動的WebアプリをFirebase中心で公開する', '{"overview":"Next.jsなど動的なWebアプリを、Firebase中心の構成で公開できるホスティングサービス。","fit":"認証・DBなどをFirebaseで揃え、Webアプリの公開までFirebaseに寄せたい場合に向く。","caution":"利用するフレームワーク、リージョン、ビルド方式、サーバー実行機能が対応範囲に含まれるか確認する。Firebase HostingやCloud Runとの役割分担も事前に整理する。","url":"https://firebase.google.com/docs/app-hosting"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 3);
